descriptor.templateCss:
.bess-cell-card {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  background: linear-gradient(160deg, rgba(14, 25, 16, 0.95) 0%, rgba(8, 15, 9, 0.98) 100%);
  border-radius: 14px;
  border: 1px solid rgba(100, 184, 86, 0.22);
  border-top: 3.5px solid #64B856;
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
  transition: border-top-color 0.3s ease;
}
.bess-cell-card.alert { border-top-color: #ef4444; }
.bess-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.card-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: #94a3b8;
}
.card-icon { font-size: 16px; }
.badge-cell {
  font-size: 11px;
  font-weight: 700;
  padding: 2px 10px;
  border-radius: 20px;
}
.badge-cell.healthy {
  color: #06b6d4;
  border: 1.5px solid #06b6d4;
  background: rgba(6, 182, 212, 0.1);
}
.badge-cell.alert {
  color: #ef4444;
  border: 1.5px solid #ef4444;
  background: rgba(239, 68, 68, 0.15);
}
.cell-kpi-body {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin: 6px 0;
}
.cell-main-delta {
  display: flex;
  align-items: baseline;
  gap: 6px;
}
.delta-num {
  font-size: 38px;
  font-weight: 800;
  color: #06b6d4;
  line-height: 1;
}
.delta-num.alert { color: #ef4444; }
.delta-unit {
  font-size: 18px;
  font-weight: 600;
  color: #94a3b8;
}
.cell-range-box {
  display: flex;
  flex-direction: column;
  gap: 4px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(100, 184, 86, 0.15);
  border-radius: 8px;
  padding: 6px 14px;
}
.cell-item {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-size: 12px;
}
.c-lbl { color: #64748b; }
.c-val { color: #e2e8f0; font-weight: 700; }
.bess-card-footer {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: #64748b;
  border-top: 1px solid rgba(148, 163, 184, 0.12);
  padding-top: 8px;
  margin-top: 4px;
}

descriptor.controllerScript:
self.onInit = function() { self.onDataUpdated(); };
self.onDataUpdated = function() {
  var data = self.ctx.data;
  var deltaMv = 14;
  var maxMv = 3285;
  var minMv = 3271;

  if (data && data.length > 0) {
    for (var i = 0; i < data.length; i++) {
      var item = data[i];
      if (item.data && item.data.length > 0) {
        var v = parseFloat(item.data[item.data.length - 1][1]);
        var k = (item.dataKey.label || item.dataKey.name || "").toLowerCase();
        if (!isNaN(v)) {
          if (k.indexOf('delta') !== -1 || i === 0) deltaMv = v;
          else if (k.indexOf('max') !== -1 || i === 1) maxMv = v;
          else if (k.indexOf('min') !== -1 || i === 2) minMv = v;
        }
      }
    }
  }

  var isHealthy = deltaMv < 30;
  var container = self.ctx.$container ? self.ctx.$container[0] : null;

  if (container) {
    var card = container.querySelector('#bess-cell-card');
    if (card) card.className = 'bess-cell-card ' + (isHealthy ? 'healthy' : 'alert');

    var elD = container.querySelector('#cell-delta-val');
    if (elD) {
      elD.textContent = Math.round(deltaMv);
      elD.className = 'delta-num ' + (isHealthy ? 'healthy' : 'alert');
    }

    var elMax = container.querySelector('#cell-max-val');
    if (elMax) elMax.textContent = Math.round(maxMv) + ' mV';

    var elMin = container.querySelector('#cell-min-val');
    if (elMin) elMin.textContent = Math.round(minMv) + ' mV';

    var elBadge = container.querySelector('#cell-health-badge');
    if (elBadge) {
      elBadge.textContent = isHealthy ? '< 30 mV SALUDABLE' : '≥ 30 mV DESBALANCE';
      elBadge.className = 'badge-cell ' + (isHealthy ? 'healthy' : 'alert');
    }
  }
};
self.onDestroy = function() {};
